-- Venue Live Guest "Ulang Tahun Moana Tropical Island". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara moana), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'moana', 'Ulang Tahun Moana Tropical Island', 'moana', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 175, 'center 38%',
  $t${"name":"Moana Tropical Island","orn":"diamond","ui":{"ivory":"#FFF8EE","white":"#FFFFFF","soft":"#FBE5CF","soft2":"#F2B98A","accent":"#E0693A","deep":"#2A7F86","ink":"#3F3A33","mute":"#9C8A74","line":"#F1DCC2","serif":"\"Fredoka\",system-ui,sans-serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Fredoka\",system-ui,sans-serif","it":0,"paper":"#FFFBF4","ink":"#3F3A33","accent":"#E0693A","gold":"#C9A24A","leaf":"#FBE5CF","hbg":"rgba(255,248,238,.94)","hline":"#C9A24A","motif":"diamond"},"hud":{"bg":"rgba(63,58,51,.9)","acc":"#8FE3E8","on":"#3F3A33"},"scr":{"wine":"#2A7F86","veil":"255,248,238"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'moana');
